import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { refreshCartItemsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await refreshCartItemsWorkflow(req.scope)
    .run({
      input: {
        cart_id: "cart_123",
      }
    })

  res.send(result)
}

